    """The positions (row, col) of every cell equal to v."""
    return [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == v]

def normalize(cells):
    """Cells translated so the top-left of their bounding box is (0, 0)."""
    mr, mc = min(r for r, c in cells), min(c for r, c in cells)
    return sorted((r - mr, c - mc) for r, c in cells)

def motif_in_zeros(grid, motif, v, w):
    """Stamp w over the cells of every window whose v-cells contain the whole motif shape."""
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    h = max(r for r, c in motif) + 1
    bw = max(c for r, c in motif) + 1
    for r in range(H - h + 1):
        for c in range(W - bw + 1):
